refentry.refsect1:
&reftitle.changelog;
&Version; &Description;
8.4.0
session 拡張モジュールが共有モジュールとしてビルドされている場合も SOAP_PERSISTENCE_SESSION が動作するようになりました。 これより前のバージョンでは、この場合は黙って失敗していました。 一方、session 拡張モジュールが利用できない状態で SOAP_PERSISTENCE_SESSION を指定すると、 SoapServer::setPersistence が Error をスローするようになりました。

  &reftitle.examples;



    SoapServer::setPersistence の例


<?php

class MyFirstPersistentSoapServer
{
    private $resource; // (PDO や mysqli など)
    public $myvar1;
    public $myvar2;

    public function __construct()
    {
        $this->resource = CodeToStartOurResourceUp(); // リソースを準備する
    }

    public function __unserialize(array $data): void
    {
        $this->myvar1 = $data['myvar1'];
        $this->myvar2 = $data['myvar2'];

        $this->resource = CodeToStartOurResourceUp();
    }

    public function __serialize(): array
    {
        // セッションデータが持続するよう、ここでは必ず $resource を除外します。
        // 除外しないと、次のリクエストでデータのアンシリアライズに失敗し、
        // MyFirstPersistentSoapServer オブジェクトがリクエスト間で持続しなくなります。
        return [
            'myvar1' => $this->myvar1,
            'myvar2' => $this->myvar2,
        ];
    }
}

try {
    session_start();
    $server = new SoapServer(null, ['uri' => $_SERVER['REQUEST_URI']]);
    $server->setClass('MyFirstPersistentSoapServer');
    // setClass は呼び出されると SOAP_PERSISTENCE_REQUEST を設定するので、
    // setPersistence は必ず setClass の後に呼び出してください。
    $server->setPersistence(SOAP_PERSISTENCE_SESSION);
    $server->handle();
} catch (SoapFault $e) {
    error_log("SOAP ERROR: " . $e->getMessage());
}
